Webhook events 
===============

[/beta/webhook\_events/list](https://plaid.com/docs/api/webhooks/webhook-events/index.html.md#betawebhook_eventslist) returns the webhooks Plaid sent to your account in the last 7 days, including webhooks that weren't delivered. Use it to recover webhooks your endpoint missed. Events are returned oldest first.

for (const event of data.webhook_events) {
    if (!alreadyProcessed(event.webhook_message_id)) {
      handleWebhookEvent(event);
    }
  }

for (const event of data.webhook_events) {
    if (!alreadyProcessed(event.webhook_message_id)) {
      handleWebhookEvent(event);
    }
  }

response.webhook_events.each do |event|
    unless already_processed(event.webhook_message_id)
      handle_webhook_event(event)
    end
  end

while (hasMore) {
  BetaWebhookEventsListRequest request = new BetaWebhookEventsListRequest()
    .cursor(cursor)
    .count(100);
  Response response = client()
    .betaWebhookEventsList(request)
    .execute();
  BetaWebhookEventsListResponse data = response.body();

for (WebhookEvent event : data.getWebhookEvents()) {
    if (!alreadyProcessed(event.getWebhookMessageId())) {
      handleWebhookEvent(event);
    }
  }

for event in response['webhook_events']:
        if not already_processed(event['webhook_message_id']):
            handle_webhook_event(event)

